<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue'
import {request} from '../lib/api'
import type {Page} from '../types'
interface StoredImage{id:string;media_type:string;size_bytes:number;sha256:string}
const props=defineProps<{jobId:string}>(),items=ref<StoredImage[]>([]),total=ref<number|null>(null),offset=ref(0),loading=ref(false),error=ref(''),selected=ref<StoredImage|null>(null),imageError=ref(false)
let controller:AbortController|undefined
async function load(){controller?.abort();controller=new AbortController();const signal=controller.signal;loading.value=true;error.value='';try{const page=await request<Page<StoredImage>>(`/jobs/${encodeURIComponent(props.jobId)}/artifacts?limit=30&offset=${offset.value}`,{signal});if(signal.aborted)return;items.value=page.items;total.value=page.total}catch(e){if(!signal.aborted){error.value=e instanceof Error?e.message:'Stored image metadata unavailable.';items.value=[];total.value=null}}finally{if(!signal.aborted)loading.value=false}}
function view(image:StoredImage){imageError.value=false;selected.value=image}
function move(delta:number){offset.value=Math.max(0,offset.value+delta);selected.value=null;void load()}
watch(()=>props.jobId,()=>{items.value=[];total.value=null;offset.value=0;selected.value=null;void load()},{immediate:true});onBeforeUnmount(()=>controller?.abort())
</script>
<template><section aria-label="Stored images" class="stored-images"><header class="table-toolbar"><div><span class="section-label">Protected evidence</span><h2>Stored images</h2><p class="helper">Images are opened only on request. A stored image does not establish playability or an authentication bypass.</p></div><q-btn flat label="Refresh images" :loading="loading" @click="load"/></header><div v-if="error" class="error-banner" role="alert">{{error}}</div><div v-else-if="loading" class="loading-label" role="status">Loading stored image metadata…</div><div v-else-if="total===0" class="empty-state"><h3>No stored images for this job</h3><p>Capture is opt-in. A job can have valid protocol or camera evidence without an image.</p></div><div v-else class="image-list"><article v-for="image in items" :key="image.id" class="stored-image-row"><div><strong>{{image.media_type==='image/jpeg'?'JPEG image':'PNG image'}}</strong><p class="helper">{{new Intl.NumberFormat().format(image.size_bytes)}} bytes · {{image.id}}</p><code>SHA-256 {{image.sha256}}</code></div><q-btn data-testid="view-stored-image" outline color="dark" label="View stored image" @click="view(image)"/></article></div><footer v-if="total!==null&&total>30" class="table-footer"><span>{{offset+1}}–{{Math.min(offset+30,total)}} of {{total}} stored images</span><q-btn flat label="Previous images" :disable="loading||offset===0" @click="move(-30)"/><q-btn flat label="Next images" :disable="loading||offset+30>=total" @click="move(30)"/></footer><q-dialog :model-value="selected!==null" @update:model-value="v=>{if(!v)selected=null}"><q-card class="image-viewer"><q-card-section class="image-viewer-head"><div><strong>Stored image</strong><p class="helper">{{selected?.id}}</p></div><q-btn v-close-popup flat label="Close image"/></q-card-section><q-card-section v-if="imageError" role="alert">This image could not be loaded. It may be unavailable or its integrity check may have failed. Refresh the list before using it as evidence.</q-card-section><q-card-section v-else-if="selected"><img data-testid="protected-image" :src="'/api/artifacts/'+encodeURIComponent(selected.id)" alt="Stored assessment image" @error="imageError=true"/></q-card-section></q-card></q-dialog></section></template>
<style scoped>.stored-images{padding:24px}.image-list{display:grid;gap:12px;margin-top:20px}.stored-image-row{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:18px;border:1px solid var(--line)}.stored-image-row code{font-size:11px;word-break:break-all}.image-viewer{width:min(1000px,96vw);max-width:96vw}.image-viewer-head{display:flex;justify-content:space-between;align-items:center;gap:20px}.image-viewer img{display:block;max-width:100%;max-height:72vh;margin:auto;object-fit:contain}@media(max-width:700px){.stored-images{padding:16px}.stored-image-row{flex-direction:column;align-items:flex-start}}</style>
